widget.solution:
from collections import deque


def shortest_path(adj, s, t):
    parent = {s: None}
    queue = deque([s])
    while queue:
        u = queue.popleft()
        if u == t:
            break
        for v in sorted(adj[u]):
            if v not in parent:
                parent[v] = u
                queue.append(v)
    if t not in parent:
        return None
    path = []
    node = t
    while node is not None:
        path.append(node)
        node = parent[node]
    return path[::-1]

